for name,changes in json.loads("{\"gallery/src/js/07d-downloads-state.js\":[[\"// One fictional transfer is controllable to test the completion moment.\\n// The existing completed download starts with its percentage hidden.\\n\",\"// Fictional transfers are controllable to test progress and completion.\\n\",1],[\"const DEMO_COMPLETION_HOLD_MS=3000;\\n\",\"\",1],[\",fullAt:new Map(),timers:new Map()\",\"\",1]],\"gallery/src/js/09-downloads-remainder.js\":[[\" const before=downloadProgress(allAnimeDownloadEntries(target.animeId));\\n\",\"\",1],[\" const after=downloadProgress(allAnimeDownloadEntries(target.animeId));\\n if(before<100&&after===100){\\n  downloadDemo.fullAt.set(target.animeId,Date.now());\\n  clearTimeout(downloadDemo.timers.get(target.animeId));\\n  const timer=setTimeout(()=>{\\n   const group=Array.from(tabPages.downloads.querySelectorAll('[data-download-group]')).find(el=>el.dataset.downloadGroup===target.animeId);\\n   group?.querySelector('.download-group-percent')?.classList.add('is-hidden');\\n  },DEMO_COMPLETION_HOLD_MS);\\n  downloadDemo.timers.set(target.animeId,timer);\\n }\\n\",\"\",1],[\" for(const timer of downloadDemo.timers.values())clearTimeout(timer);\\n\",\"\",1],[\"downloadDemo.fullAt.clear();downloadDemo.timers.clear();\",\"\",1]],\"gallery/src/js/15-source-state-initialization.js\":[[\"let sourceDemoOpToken=0;\\nfunction resetSourcesPreview(){\\n sourceDemoOpToken++;\",\"let sourceDemoOpToken=0;\\nlet sourceDemoTimer=null;\\nfunction cancelSourceOperationTimer(){\\n const handle=sourceDemoTimer;\\n sourceDemoTimer=null;\\n if(handle!==null)clearTimeout(handle);\\n}\\nfunction scheduleSourceOperation(token,callback,delay){\\n if(token!==sourceDemoOpToken)return;\\n cancelSourceOperationTimer();\\n const handle=setTimeout(()=>{\\n  if(sourceDemoTimer!==handle||token!==sourceDemoOpToken)return;\\n  sourceDemoTimer=null;\\n  callback();\\n },delay);\\n sourceDemoTimer=handle;\\n}\\nfunction resetSourcesPreview(){\\n sourceDemoOpToken++;\\n cancelSourceOperationTimer();\",1]],\"gallery/src/js/17a-sources.js\":[[\"function sourceOperationEnd(){sourceDemoBusy=null;sourceDemoBusyAction=null;sourceDemoPhase=-1;}\",\"function sourceOperationEnd(){cancelSourceOperationTimer();sourceDemoBusy=null;sourceDemoBusyAction=null;sourceDemoPhase=-1;}\",1],[\"setTimeout(()=>{\\n    if(token!==sourceDemoOpToken)return;\",\"scheduleSourceOperation(token,()=>{\\n    if(token!==sourceDemoOpToken)return;\",1],[\"setTimeout(()=>advance(phase+1),850)\",\"scheduleSourceOperation(token,()=>advance(phase+1),850)\",1],[\"setTimeout(()=>{\\n   if(token!==sourceDemoOpToken)return;\",\"scheduleSourceOperation(token,()=>{\\n   if(token!==sourceDemoOpToken)return;\",2],[\"setTimeout(()=>advance(1),700)\",\"scheduleSourceOperation(token,()=>advance(1),700)\",1]],\"gallery/tests/test_player_settings_regression.py\":[[\"subprocess.run([sys.executable,str(Path(__file__).resolve().parents[1]/'audits'/'2026-11-17-a2-dialog-settings-ownership-retry-regression.py'),sys.argv[1]],check=True)\",\"subprocess.run([sys.executable,str(Path(__file__).resolve().parents[1]/'audits'/'2026-11-17-a2-dialog-settings-ownership-retry-regression.py'),sys.argv[1]],check=True)\\n\\n# Mandatory A2.5 background operation ownership regression.\\nsubprocess.run([sys.executable,str(Path(__file__).resolve().parents[1]/'audits'/'2026-11-18-a2-background-operation-ownership-regression.py'),sys.argv[1]],check=True)\",1]]}").items():
    path=Path(name)
